fix_code:
public static void main(String[]args){
  Scanner sc = new Scanner(System.in);

  int n = sc.nextInt();
  int [] a = new int[n-1];
  int count = 0;
  for(int i = 0; i < n-1; i++){ // Corrected loop condition
    a[i] = sc.nextInt();
    count = count + a[i];
  }

  System.out.println(-count); // The final score of person N is the negative sum of the scores of persons 1 to N-1.
}

